global.requestAnimationFrame = cb => { frames.set(++frameId, cb); return frameId; };
global.cancelAnimationFrame = id => frames.delete(id);
const listeners = {}, saves = new Map(), loadedPackages = new Set(), exported = [], exportedImages = [];
const api = {
  createCanvas() {
    const canvas = createCanvas(1, 1);
    canvas.toTempFilePath = options => {
      assert.equal(options.fileType, 'png');
      assert.equal(options.destWidth, canvas.width); assert.equal(options.destHeight, canvas.height);
      const tempFilePath = path.join(out, 'user-export-complete.png');
      fs.writeFileSync(tempFilePath, canvas.toBuffer('image/png'));
