        image.onload?.();
      }).catch(error => image.onerror?.(error));
    } });
    return image;
  },
  getPerformance: () => ({ now: () => time * 1000 }),
  getWindowInfo: () => ({ windowWidth: 390, windowHeight: 844, pixelRatio: 2, safeArea: { left: 0, top: 28, right: 390, bottom: 824 } }),
  getStorageSync: key => saves.get(key) ?? '', setStorageSync: (key, value) => saves.set(key, structuredClone(value)), removeStorageSync: key => saves.delete(key),
  loadSubpackage({ name, success }) { loadedPackages.add(name); success(); },
  showToast() {}, showModal({ success }) { success({ confirm: true }); },
  env: { USER_DATA_PATH: out }, getFileSystemManager: () => ({ writeFileSync(p, data) { fs.writeFileSync(p, data); } }),
  setClipboardData({ data, success }) { exported.push(data); success(); }, getClipboardData({ success }) { success({ data: exported.at(-1) || '' }); },
