      assert.equal(game.session.select(id), false, 'transition locks input');
      await step(1350); await step(700); snap(host.canvas, `overview-after-${state.activeBlockId}`); await step(450); await step(800);
      const next = game.session.getSnapshot().activeBlockId; if (next && !visited.includes(next)) visited.push(next);
    } else await step(1350);
