  game.overview = true; game.camera = game.cameraForOverview(); game.dirty = true; await step(1); snap(host.canvas, '05-complete-mobile');
  const exportButton = game.hits.find(h => h.id === 'export-image'); assert.ok(exportButton, 'completed scene has an explicit image export action');
  click(exportButton.x + exportButton.width / 2, exportButton.y + exportButton.height / 2);
