import { resLoader } from '../../../oops-framework/core/common/loader/ResLoader';
import type { TheatreRuntimeServices } from '../cocos/TheatreGame';

/** Called from Root.run(), after config and StorageManager initialization. */
export function createOopsTheatreRuntime(): TheatreRuntimeServices {
  if (!oops.storage) throw new Error('Oops StorageManager 尚未初始化');
  return {
    async loadJson(path: string): Promise<JsonAsset> {
      const asset = await resLoader.load<JsonAsset>('resources', path, JsonAsset);
      // Upstream load() resolves null on failure, rather than rejecting.
      if (!asset) throw new Error(`剧院 JSON 加载失败：${path}`);
      return asset;
    },
    async loadSpriteFrame(path: string): Promise<SpriteFrame> {
      const frame = await resLoader.load<SpriteFrame>('resources', path, SpriteFrame);
      if (!frame) throw new Error(`剧院贴纸加载失败：${path}`);
      return frame;
    },
    getItem(key: string): string | null {
      const text = oops.storage.get(key);
      return text === '' || text == null ? null : text;
    },
    setItem(key: string, value: string): void {
      // Keep JSON text intact; StorageManager encodes strings without double serialization.
      oops.storage.set(key, value);
    },
  };
}

