/** Draws the base and all 91 native parts in one global order, without alpha gates. */
private drawWorld(c: any, layout: any, placed: Set<string>): void {
  const base = this.images.get(layout.scene.baseAssetKey);
  if (base) c.drawImage(base, 0, 0, layout.scene.width, layout.scene.height);
  const stickerMap = new Map<string, any>(layout.stickers.map((s: any) => [s.stickerId, s]));
  const fixedMap = new Map<string, any>(layout.fixedLayers.map((f: any) => [f.fixedId, f]));
  for (const entry of layout.renderOrder.slice().sort((a: any, b: any) => a.placementOrder - b.placementOrder)) {
    if (entry.kind === 'fixed') {
      const f = fixedMap.get(entry.fixedId); if (!f || !(f.requiresAssetIds || []).every((id: string) => placed.has(id))) continue;
      const image = this.images.get(f.assetKey); if (!image) continue;
      c.save(); c.translate(f.position.x, f.position.y); c.rotate((f.rotation || 0) * Math.PI / 180); c.scale(f.scale || 1, f.scale || 1);
