  private skipEmptyBlocks(start: number): number {
    let index = start;
    while (index < this.blocks.length && this.blockStickers.get(this.blocks[index].blockId)!.length === 0) index++;
    return index;
  }

  private activeLevel(blockIndex: number, placed: Set<string>): AreaLevel | null {
    const members = this.blockStickers.get(this.blocks[blockIndex]?.blockId ?? '') ?? [];
    return AREA_LEVELS.find(level => members.some(sticker => sticker.areaLevel === level && !placed.has(sticker.stickerId))) ?? null;
  }

  private readyIds(): string[] {
    const level = this.activeLevel(this.blockIndex, this.placed);
    return (this.blockStickers.get(this.blocks[this.blockIndex]?.blockId ?? '') ?? [])
      .filter(sticker => sticker.areaLevel === level && !this.placed.has(sticker.stickerId)
        && (sticker.dependsOn ?? []).every(id => this.placed.has(id)))
      .map(sticker => sticker.stickerId);
  }

  private matchesTicket(ticket: PlacementTicket): boolean {
    return record(ticket) && !!this.pending && ticket.stickerId === this.pending.stickerId
      && ticket.transactionId === this.pending.transactionId;
  }

  private replay(history: string[]): ReplayedHistory {
    const placed = new Set<string>();
    let nextBlockIndex = this.skipEmptyBlocks(0);
    let lastCompletedBlockIndex: number | null = null;
    const errors: string[] = [];
    for (const [index, id] of history.entries()) {
      const sticker = this.stickers.get(id);
      if (!sticker) { errors.push(`history[${index}] has unknown sticker ${id}`); break; }
      if (placed.has(id)) { errors.push(`history[${index}] repeats sticker ${id}`); break; }
      if (sticker.geoBlock !== this.blocks[nextBlockIndex]?.blockId) {
        errors.push(`history[${index}] enters a block before the previous block is complete`); break;
      }
      if (sticker.areaLevel !== this.activeLevel(nextBlockIndex, placed)) {
        errors.push(`history[${index}] violates L1/L2/L3 stage order`); break;
      }
      if (!(sticker.dependsOn ?? []).every(dependency => placed.has(dependency))) {
        errors.push(`history[${index}] violates sticker dependencies`); break;
      }
      placed.add(id);
      lastCompletedBlockIndex = null;
      if (this.activeLevel(nextBlockIndex, placed) === null) {
        lastCompletedBlockIndex = nextBlockIndex;
        nextBlockIndex = this.skipEmptyBlocks(nextBlockIndex + 1);
      }
    }
    return { placed, nextBlockIndex, lastCompletedBlockIndex, errors };
  }

  private emit(event: Omit<SessionEvent, 'revision'>): void {
    this.revision++;
    const completeEvent: SessionEvent = { ...event, revision: this.revision };
    // Capture once before listeners: a listener may synchronously perform another action.
    const snapshot = this.getSnapshot();
    for (const listener of [...this.listeners]) listener(clone(snapshot), { ...completeEvent });
  }
}

export type StickerDraftPatch = Partial<Pick<StickerPlacement,
  'position' | 'scale' | 'rotation' | 'areaLevel' | 'geoBlock' | 'layerIndex' | 'anchor'>>;

/** Pure JSON draft helpers. They never load, cut, transform or write raster files. */
export function createLayoutDraft(layout: GameLayout): GameLayout {
  assertLayout(layout);
  return clone(layout);
}

export function patchStickerDraft(layout: GameLayout, stickerId: string, patch: StickerDraftPatch): GameLayout {
  const draft = createLayoutDraft(layout);
  const sticker = draft.stickers.find(entry => entry.stickerId === stickerId);
  if (!sticker) throw new Error(`Unknown sticker ${stickerId}`);
  const allowed = new Set(['position', 'scale', 'rotation', 'areaLevel', 'geoBlock', 'layerIndex', 'anchor']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new Error(`Unsupported editable sticker field ${key}`);
    (sticker as Record<string, unknown>)[key] = clone((patch as Record<string, unknown>)[key]);
  }
  assertLayout(draft);
  refreshPlayMetadata(draft);
  return draft;
}

/**
 * Explicit reorder only. Omitting IDs sorts coarse layerIndex, then existing order.
 * In a multipart scene, retain each owner's relative part-layer differences and
 * include fixed foreground in the same global queue; never collapse a person into
 * one contiguous layer. For an exact custom queue use reorderRenderPartsDraft.
 */
export function reorderDraft(layout: GameLayout, orderedStickerIds?: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (draft.renderOrder?.length) {
    if (orderedStickerIds) {
      throw new Error('Multipart scenes require an explicit render-part queue; use reorderRenderPartsDraft');
    }
    const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
    for (const entry of draft.renderOrder) {
      if (entry.kind !== 'stickerPart') continue;
      const sticker = stickers.get(entry.stickerId ?? '');
      const parts = sticker?.renderParts;
      const part = parts?.find(candidate => candidate.partId === entry.partId);
      if (!sticker || !parts?.length || !part) throw new Error(`Invalid render queue part ${entry.partId}`);
      const sourceLayer = Math.min(...parts.map(candidate => candidate.layerIndex));
      entry.layerIndex = sticker.layerIndex + part.layerIndex - sourceLayer;
    }
    draft.renderOrder.sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder);
    synchronizeRenderOrders(draft);
    refreshPlayMetadata(draft);
    assertLayout(draft);
    return draft;
  }
  const ids = orderedStickerIds ? [...orderedStickerIds]
    : [...draft.stickers].sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder)
      .map(sticker => sticker.stickerId);
  const known = new Set(draft.stickers.map(sticker => sticker.stickerId));
  if (ids.length !== known.size || new Set(ids).size !== known.size || ids.some(id => !known.has(id))) {
    throw new Error('Reorder must include every sticker ID exactly once');
  }
  const rank = new Map(ids.map((id, index) => [id, (index + 1) * 10]));
  for (const sticker of draft.stickers) sticker.placementOrder = rank.get(sticker.stickerId)!;
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

/** Stable identity for an entry in the single global part/fixed painter queue. */
export function renderEntryKey(entry: RenderQueueEntry): string {
  return entry.kind === 'fixed' ? `fixed:${entry.fixedId}` : `stickerPart:${entry.partId}`;
}

export function reorderRenderPartsDraft(layout: GameLayout, orderedEntryKeys: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (!draft.renderOrder) throw new Error('Layout has no render-part queue');
  const entries = new Map(draft.renderOrder.map(entry => [renderEntryKey(entry), entry]));
  if (entries.size !== draft.renderOrder.length || orderedEntryKeys.length !== entries.size
    || new Set(orderedEntryKeys).size !== entries.size || orderedEntryKeys.some(key => !entries.has(key))) {
    throw new Error('Render-part reorder must include every part/fixed entry exactly once');
  }
  draft.renderOrder = orderedEntryKeys.map(key => entries.get(key)!);
  synchronizeRenderOrders(draft);
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

function synchronizeRenderOrders(draft: GameLayout): void {
  const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
  const fixed = new Map((draft.fixedLayers ?? []).map(layer => [layer.fixedId, layer]));
  for (const [index, entry] of (draft.renderOrder ?? []).entries()) {
    entry.placementOrder = (index + 1) * 10;
    entry.paintOrder = entry.placementOrder;
    if (entry.kind === 'fixed') {
      const layer = fixed.get(entry.fixedId ?? '');
      if (!layer) throw new Error(`Unknown fixed render layer ${entry.fixedId}`);
      layer.placementOrder = entry.placementOrder;
      layer.paintOrder = entry.placementOrder;
      layer.layerIndex = entry.layerIndex;
    } else {
      const part = stickers.get(entry.stickerId ?? '')?.renderParts?.find(candidate => candidate.partId === entry.partId);
      if (!part) throw new Error(`Unknown render part ${entry.partId}`);
      part.placementOrder = entry.placementOrder;
      part.paintOrder = entry.placementOrder;
      part.layerIndex = entry.layerIndex;
    }
  }
  for (const sticker of draft.stickers) {
    if (sticker.renderParts?.length) sticker.placementOrder = Math.min(...sticker.renderParts.map(part => part.placementOrder));
  }
}

/** Update denormalized gameplay metadata without changing source transforms/offsets. */
function refreshPlayMetadata(draft: GameLayout): void {

export function validateLayout(value: unknown): string[] {
  const errors: string[] = [];
  if (!record(value)) return ['layout must be an object'];
  if (!identifier(value.sceneId)) errors.push('sceneId must be a nonempty string');
  if (!identifier(value.layoutRevision) && !(integer(value.layoutRevision) && value.layoutRevision >= 0)) {
    errors.push('layoutRevision must be a nonempty string or nonnegative safe integer');
  }
  if (!Array.isArray(value.geoBlocks)) errors.push('geoBlocks must be an array');
  if (!Array.isArray(value.stickers)) errors.push('stickers must be an array');
  if (errors.length) return errors;
  const blockOrders = new Set<number>();
  const blocks = new Map<string, GeoBlock>();
  for (const [index, entry] of Array.from(value.geoBlocks as unknown[]).entries()) {
    const label = `geoBlocks[${index}]`;
    if (!record(entry)) { errors.push(`${label} must be an object`); continue; }
    if (!identifier(entry.blockId)) errors.push(`${label}.blockId must be nonempty`);
    else if (blocks.has(entry.blockId)) errors.push(`duplicate blockId ${entry.blockId}`);
    else blocks.set(entry.blockId, entry as unknown as GeoBlock);
    if (!integer(entry.blockOrder) || entry.blockOrder < 0) {
      errors.push(`${label}.blockOrder must be a nonnegative safe integer`);
    } else if (blockOrders.has(entry.blockOrder)) {
      errors.push(`duplicate blockOrder ${entry.blockOrder}`);
    } else blockOrders.add(entry.blockOrder);
  }
  const stickers = new Map<string, StickerPlacement>();
  const renderOrders = new Set<number>();
  for (const [index, entry] of Array.from(value.stickers as unknown[]).entries()) {
    const label = `stickers[${index}]`;
    if (!record(entry)) { errors.push(`${label} must be an object`); continue; }
    if (!identifier(entry.stickerId)) errors.push(`${label}.stickerId must be nonempty`);
    else if (stickers.has(entry.stickerId)) errors.push(`duplicate stickerId ${entry.stickerId}`);
    else stickers.set(entry.stickerId, entry as unknown as StickerPlacement);
    if (!identifier(entry.geoBlock) || !blocks.has(entry.geoBlock)) {
      errors.push(`${label}.geoBlock must reference an existing block`);
    }
    if (!AREA_LEVELS.includes(entry.areaLevel as AreaLevel)) errors.push(`${label}.areaLevel must be L1, L2 or L3`);
    if (!integer(entry.placementOrder) || entry.placementOrder < 0) {
      errors.push(`${label}.placementOrder must be a nonnegative safe integer`);
    } else if (renderOrders.has(entry.placementOrder)) {
      errors.push(`duplicate placementOrder ${entry.placementOrder}`);
    } else renderOrders.add(entry.placementOrder);
    if (!integer(entry.layerIndex)) errors.push(`${label}.layerIndex must be a safe integer`);
    if (!record(entry.position) || !finite(entry.position.x) || !finite(entry.position.y)) {
      errors.push(`${label}.position must contain finite x and y`);
    }
    if (!record(entry.anchor) || !finite(entry.anchor.x) || !finite(entry.anchor.y)
      || entry.anchor.x < 0 || entry.anchor.x > 1 || entry.anchor.y < 0 || entry.anchor.y > 1) {
      errors.push(`${label}.anchor must contain normalized x and y in [0, 1]`);
    }
    if (!record(entry.sourceSize) || !finite(entry.sourceSize.width) || !finite(entry.sourceSize.height)
      || entry.sourceSize.width <= 0 || entry.sourceSize.height <= 0) {
      errors.push(`${label}.sourceSize must contain positive width and height`);
    }
    if (!finite(entry.scale) || entry.scale <= 0) errors.push(`${label}.scale must be positive and finite`);
    if (!finite(entry.rotation)) errors.push(`${label}.rotation must be finite degrees`);
    if (entry.dependsOn !== undefined && (!Array.isArray(entry.dependsOn)
      || Array.from(entry.dependsOn).some(id => !identifier(id)))) {
      errors.push(`${label}.dependsOn must be an array of sticker IDs`);
    }
  }
  // Avoid operating on malformed references while collecting useful errors.
  if (errors.length) return errors;
  for (const sticker of stickers.values()) {
    const seen = new Set<string>();
    for (const dependencyId of sticker.dependsOn ?? []) {
      if (seen.has(dependencyId)) errors.push(`${sticker.stickerId} has duplicate dependency ${dependencyId}`);
      seen.add(dependencyId);
      const dependency = stickers.get(dependencyId);
      if (!dependency) { errors.push(`${sticker.stickerId} has unknown dependency ${dependencyId}`); continue; }
      if (dependencyId === sticker.stickerId) errors.push(`${sticker.stickerId} depends on itself`);
      const block = blocks.get(sticker.geoBlock)!;
      const dependencyBlock = blocks.get(dependency.geoBlock)!;
      if (dependencyBlock.blockOrder > block.blockOrder) {
        errors.push(`${sticker.stickerId} depends on future block sticker ${dependencyId}`);
      } else if (dependency.geoBlock === sticker.geoBlock && levelRank(dependency.areaLevel) > levelRank(sticker.areaLevel)) {
        errors.push(`${sticker.stickerId} depends on a later areaLevel sticker ${dependencyId}`);
      }
    }
  }
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const walk = (id: string): void => {
    if (visiting.has(id)) { errors.push(`dependency cycle at ${id}`); return; }
    if (visited.has(id)) return;
    visiting.add(id);
    for (const dependency of stickers.get(id)?.dependsOn ?? []) if (stickers.has(dependency)) walk(dependency);
    visiting.delete(id);
    visited.add(id);
  };
  for (const id of stickers.keys()) walk(id);
  return errors;
}

export class LayoutValidationError extends Error {
  readonly errors: string[];
  constructor(errors: string[]) {
    super(`Invalid sticker layout: ${errors.join('; ')}`);
    this.errors = [...errors];
    this.name = 'LayoutValidationError';
  }
}

function assertLayout(layout: unknown): asserts layout is GameLayout {
  const errors = validateLayout(layout);
  if (errors.length) throw new LayoutValidationError(errors);
}

import { CanvasGame } from '../../rendering/CanvasGame';

declare const wx: any;
declare function requestAnimationFrame(callback: (time: number) => void): number;
declare function cancelAnimationFrame(id: number): void;

export interface AssetSubpackage { prefix: string; name: string }
export interface WechatOptions {
  api?: any;
  assetSubpackages?: AssetSubpackage[];
  preloadSubpackages?: string[];
}
const DEFAULT_PACKAGES: AssetSubpackage[] = ['base', 'reference', 'assets', 'parts', 'fixed']
  .map(folder => ({ prefix: `resources/${folder}/`, name: `theatre-${folder}` }));

/** Host API only; game state, world coordinates and drawing stay in shared code. */
export async function startWechatGame(layout: any, options: WechatOptions = {}) {
  const api = options.api || wx;
  // The FIRST wx.createCanvas is on-screen. Later canvases are off-screen.
  const canvas = api.createCanvas();
  const packages = options.assetSubpackages || DEFAULT_PACKAGES;
  const loads = new Map<string, Promise<void>>();
  const images = new Map<string, Promise<any>>();
  const performanceClock = api.getPerformance ? api.getPerformance() : null;
  // Official Mini Game Performance.now is MICROseconds, not browser milliseconds.
  const now = () => performanceClock ? performanceClock.now() / 1000 : Date.now();
  const toast = (message: string) => api.showToast({ title: String(message), icon: 'none', duration: 2800 });
  const loadPackage = (name: string): Promise<void> => {
    if (!loads.has(name)) {
      const pending = new Promise<void>((resolve, reject) => {
        if (!api.loadSubpackage) { reject(new Error('当前微信版本不支持素材分包，请更新微信')); return; }
        api.loadSubpackage({ name, success: () => resolve(), fail: reject });
      }).catch(error => { loads.delete(name); throw error; });
      loads.set(name, pending);
    }
    return loads.get(name)!;
  };
  const importJson = (): Promise<string | null> => new Promise((resolve, reject) => {
    api.getClipboardData({ success: (result: any) => {
      const text = String(result.data || '').trim();
      if (!text) { toast('请先复制排布 JSON，再点导入'); resolve(null); } else resolve(text);
    }, fail: reject });
  });
  const platform = {
    createCanvas(width: number, height: number) {
      const offscreen = api.createCanvas();
      offscreen.width = Math.max(1, Math.ceil(width)); offscreen.height = Math.max(1, Math.ceil(height));
      return offscreen;
    },
    loadImage(assetKey: string): Promise<any> {
      if (!images.has(assetKey)) {
        const bundle = packages.find(pack => assetKey.startsWith(pack.prefix));
        const ready = bundle ? loadPackage(bundle.name) : Promise.resolve();
        images.set(assetKey, ready.then(() => new Promise((resolve, reject) => {
          const image = api.createImage();
          image.onload = () => resolve(image);
          image.onerror = (error: any) => reject(new Error(`无法读取素材 ${assetKey}: ${error?.errMsg || 'image error'}`));
          image.src = assetKey;
        })).catch(error => { images.delete(assetKey); throw error; }));
      }
      return images.get(assetKey)!;
    },
    storage: {
      get(key: string) { const value = api.getStorageSync(key); return value === '' || value === undefined ? null : value; },
      set(key: string, value: any) { api.setStorageSync(key, value); },
      remove(key: string) { api.removeStorageSync(key); },
    },
    now,
