    },
    async exportImage(imageCanvas: any): Promise<void> {
      const filePath = await new Promise<string>((resolve, reject) => {
        imageCanvas.toTempFilePath({ fileType: 'png', x: 0, y: 0,
          width: imageCanvas.width, height: imageCanvas.height,
