  };
  const game: any = new CanvasGame({ canvas, layout, platform });
  let pointer: number | null = null, ready = false, hidden = false;
  const clamp = (value: number, max: number) => Math.max(0, Math.min(max, value));
  const resize = (event?: any) => {
    const info = api.getWindowInfo ? api.getWindowInfo() : api.getSystemInfoSync();
    const width = event?.windowWidth || info.windowWidth;
    const height = event?.windowHeight || info.windowHeight;
    const safe = info.safeArea;
    const screenTop = info.screenTop || 0;
    const left = safe ? clamp(safe.left, width) : 0;
    const top = safe ? clamp(safe.top - screenTop, height) : 0;
    const right = safe ? clamp(safe.right, width) : width;
    const bottom = safe ? clamp(safe.bottom - screenTop, height) : height;
    game.resize(width, height, info.pixelRatio || 1,
      { left, top, right, bottom, width: Math.max(0, right - left), height: Math.max(0, bottom - top) });
  };
  const cancel = () => { if (pointer !== null) game.pointerCancel(pointer); pointer = null; };
  const findPointer = (event: any) => Array.from(event.changedTouches || event.touches || [])
    .find((touch: any) => touch.identifier === pointer) as any;
  const down = (event: any) => {
    if (!ready || hidden || pointer !== null) return;
    const touch = (event.changedTouches || event.touches || [])[0];
    if (touch) { pointer = touch.identifier; game.pointerDown(touch.clientX, touch.clientY, pointer); }
  };
  const move = (event: any) => {
    if (!ready || pointer === null) return;
    const touch = findPointer(event);
    if (touch) game.pointerMove(touch.clientX, touch.clientY, pointer);
  };
  const up = (event: any) => {
    if (!ready || pointer === null) return;
    const touch = findPointer(event);
    if (touch) { game.pointerUp(touch.clientX, touch.clientY, pointer); pointer = null; }
  };
  const touchCancel = (event: any) => {
    if (pointer !== null && (!event?.changedTouches?.length || findPointer(event))) cancel();
  };
  const hide = () => { hidden = true; cancel(); game.suspend(); };
  const show = () => { hidden = false; resize(); if (ready) game.resume(); };
  const windowResize = (event: any) => { cancel(); resize(event); };
  const listeners: [string, (...args: any[]) => void][] = [
    ['TouchStart', down], ['TouchMove', move], ['TouchEnd', up], ['TouchCancel', touchCancel],
    ['Hide', hide], ['Show', show], ['WindowResize', windowResize],
  ];
  listeners.forEach(([name, handler]) => api[`on${name}`]?.(handler));
  resize();
  try {
    await Promise.all((options.preloadSubpackages || []).map(loadPackage));
    await game.start(); ready = true;
    if (hidden) game.suspend();
  } catch (error) {
    listeners.forEach(([name, handler]) => api[`off${name}`]?.(handler));
    game.suspend(); throw error;
  }
  return { game, platform, canvas, dispose() {
    ready = false; cancel(); game.suspend();
    listeners.forEach(([name, handler]) => api[`off${name}`]?.(handler));
    images.clear();
  } };
}

