import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  GameSession, validateLayout, createLayoutDraft, patchStickerDraft,
  reorderDraft, reorderRenderPartsDraft, renderEntryKey,
} from '../../outputs/theatre-game/src/core/GameSession.ts';

const here = path.dirname(fileURLToPath(import.meta.url));
const project = path.resolve(here, '../..');
const layout = JSON.parse(fs.readFileSync(path.join(project, 'outputs/theatre-game/data/theatre-layout.json'), 'utf8'));
const clone = value => JSON.parse(JSON.stringify(value));
const checks = [];
const check = (name, run) => { run(); checks.push(name); };
const put = (session, id) => {
  assert.equal(session.select(id), true, `select ${id}`);
  const ticket = session.beginPlacement(id);
  assert.ok(ticket, `begin ${id}`);
  assert.equal(session.commitPlacement(ticket), true, `commit ${id}`);
  return ticket;
};
const placement = (id, block, level, order, dependencies = []) => ({
  stickerId: id, geoBlock: block, areaLevel: level, placementOrder: order, layerIndex: 0,
  position: { x: 10, y: 20 }, anchor: { x: 0, y: 0 },
  sourceSize: { width: 60, height: 80 }, scale: 1, rotation: 0, dependsOn: dependencies,
});
const fixture = {
  sceneId: 'test-scene', layoutRevision: 1,
  // Unsorted blocks and empty block deliberately exercise declared blockOrder.
  geoBlocks: [
    { blockId: 'second', blockOrder: 20 },
    { blockId: 'empty', blockOrder: 0 },
    { blockId: 'first', blockOrder: 10 },
  ],
  stickers: [
    placement('a', 'first', 'L1', 100),
    placement('b', 'first', 'L1', 10, ['a']),
    placement('c', 'first', 'L3', 30, ['b']),
    placement('d', 'second', 'L2', 20, ['c']),
    placement('e', 'second', 'L3', 5, ['d']),
  ],
};

check('actual package: valid 61 independent sticker placements in 7 blocks', () => {
  assert.deepEqual(validateLayout(layout), []);
  assert.equal(layout.stickers.length, 61);
  assert.equal(layout.geoBlocks.length, 7);
  const first = new GameSession(layout).getSnapshot();
  assert.equal(first.activeBlockId, 'upper_costume');
  assert.equal(first.activeAreaLevel, 'L1');
  assert.deepEqual(first.availableStickerIds, ['L035']);
  assert.equal(first.progress.placed, 0);
});

check('immutable input and snapshots: adapter mutations cannot alter session', () => {
  const input = clone(fixture);
  const session = new GameSession(input);
  input.stickers[0].areaLevel = 'L3';
  const snapshot = session.getSnapshot();
  snapshot.availableStickerIds.push('fake');
  snapshot.progress.blocks[0].placed = 200;
  const copy = session.getLayout();
  copy.stickers[0].position.x = 999;
  assert.deepEqual(session.getSnapshot().availableStickerIds, ['a']);
  assert.equal(session.getLayout().stickers[0].position.x, 10);
});

check('independent play/render order, dependencies and automatic empty-stage skipping', () => {
  const session = new GameSession(fixture);
  assert.equal(session.getSnapshot().activeBlockId, 'first');
  assert.deepEqual(session.getSnapshot().availableStickerIds, ['a']);
  assert.equal(session.select('b'), false);
  assert.equal(session.select('c'), false);
  assert.equal(session.select('d'), false);
  put(session, 'a');
  assert.deepEqual(session.getSnapshot().availableStickerIds, ['b']);
  put(session, 'b');
  assert.equal(session.getSnapshot().activeAreaLevel, 'L3');
  assert.deepEqual(session.getSnapshot().renderStickerIds, ['b', 'a']);
  put(session, 'c');
  assert.equal(session.getSnapshot().phase, 'transitioning');
  assert.equal(session.getSnapshot().canUndo, false);
  assert.equal(session.select('d'), false);
  assert.equal(session.undo(), false);
  assert.equal(session.finishTransition(), true);
  assert.equal(session.finishTransition(), false);
  assert.equal(session.getSnapshot().activeBlockId, 'second');
  assert.equal(session.getSnapshot().activeAreaLevel, 'L2');
  put(session, 'd');
  put(session, 'e');
  assert.equal(session.getSnapshot().phase, 'transitioning');
  assert.equal(session.finishTransition(), true);
  assert.equal(session.getSnapshot().phase, 'completed');
  assert.equal(session.getSnapshot().canUndo, true);
  assert.equal(session.getSnapshot().activeBlockId, null);
  assert.deepEqual(session.getSnapshot().renderStickerIds, ['e', 'b', 'd', 'c', 'a']);
});

check('commit tickets prevent duplicate, wrong and stale animation callbacks', () => {
